//! `/roku-logs` — capture device logs over ECP.
//!
//! The slash-command API only returns output after the process exits, so
//! this is a bounded capture, not a live stream. For live logs use the
//! `roku: logs` task generated by `/roku-init` (it runs in a terminal).

use crate::cli;
use zed_extension_api::{Result, Worktree};

pub fn run(args: &[String], worktree: &Worktree) -> Result<String, String> {
    let mut cli_args = vec!["logs".to_string(), "--once".to_string()];
    cli_args.extend(args.iter().cloned());
    let output = cli::run(worktree, &cli_args)?;
    Ok(format!("## roku logs\n\n```\n{output}\n```"))
}
